fun withFallback(value: Any): String =
    value as? String ?: "<fallback>"   // never throws

// The erasure lie: compiles, then ClassCastException at runtime
val items = mutableListOf<Any>(1, "two", 3)
val strings = items as List<String>   // unchecked cast warning
strings[1].uppercase()                // 1 is not a String -> CCE

class UserStore {
    var user: User? = null        // var property — no smart cast possible

    fun render() {
        // error: smart cast impossible because 'user' is a mutable property
        // if (user != null) println(user.name)

        // fix 1 — a stable local copy
        val u = user
        if (u != null) println(u.name)

        // fix 2 — let
        user?.let { println(it.name) }
    }
}

// A contract enables smart casts across a function boundary
import kotlin.contracts.ExperimentalContracts
import kotlin.contracts.contract

fun requireNonNull(x: Any?): String {
    contract { returns() implies (x != null) }
    return x.toString()
}

