// Roughly what the JVM sees (public function => parameter checks)
fun greet(name: String, prefix: String) {
    Intrinsics.checkNotNullParameter(name, "name")
    Intrinsics.checkNotNullParameter(prefix, "prefix")
    println("$prefix, $name")
}

// Generic T: no check emitted, however you declare it
fun <T> passthrough(x: T): T = x   // null slips in from Java without a throw

// Java side, unannotated:  public User findById(long id)  — may return null

// Kotlin seam — the ONLY file that sees the platform type
class UserRepository(private val dao: LegacyUserDao) {
    fun findById(id: Long): User? = dao.findById(id)      // explicit nullable
    fun findOrThrow(id: Long): User =
        dao.findById(id) ?: error("no user $id")          // explicit non-null
}

